  ('e1c8f24b-ba88-49c4-a9db-b289f45262ea', '2026-10-01T09:00:00.000Z', null, '2026-10-01T09:00:00.000Z', null, 'php-ship-breaking-recycling', 'PHP Ship Breaking & Recycling Industries Ltd', 'পিএইচপি শিপ ব্রেকিং অ্যান্ড রিসাইক্লিং ইন্ডাস্ট্রিজ লিমিটেড', 'green', 'PHP Family', 'Sitalpur, Sitakunda, Chattogram, Bangladesh', 'শীতলপুর, সীতাকুণ্ড, চট্টগ্রাম, বাংলাদেশ', 22.461618, 91.72863, 'Mr. Zahirul Islam (Rinku), Managing Director', '+88 01919 924477', 'zahir@phpfamily.com', 'https://phpfamily.com', true, null, null, true, 'Bangladesh Ship Recycling Board (BSRB)', 'BSRB/2025/SRF 001', '2025-10-30', '2030-10-29', 'PHP Ship Breaking & Recycling Industries Ltd is an IMO-authorised ship recycling facility under the Hong Kong Convention (DASR: BSRB/2025/SRF 001), located at Sitalpur, Sitakunda, Chattogram, Bangladesh. Its Document of Authorization to Conduct Ship Recycling is issued by the Bangladesh Ship Recycling Board (BSRB) and is valid until 29 October 2030.', 'পিএইচপি শিপ ব্রেকিং অ্যান্ড রিসাইক্লিং ইন্ডাস্ট্রিজ লিমিটেড হংকং কনভেনশনের আওতায় অনুমোদিত একটি জাহাজ পুনর্ব্যবহার স্থাপনা (ডিএএসআর: BSRB/2025/SRF 001), যা শীতলপুর, সীতাকুণ্ড, চট্টগ্রাম, বাংলাদেশ-এ অবস্থিত। বাংলাদেশ শিপ রিসাইক্লিং বোর্ডের (বিএসআরবি) দেওয়া এই অনুমোদন ২০৩০ সালের ২৯ অক্টোবর পর্যন্ত কার্যকর।', array['Impermeable concrete cutting floor', 'Heavy crawler & tower cranes', 'Hazardous waste containment shed', 'Worker safety & training center', 'Primary medical care clinic']::text[], array['অপ্রবেশ্য কংক্রিটের কাটিং ফ্লোর', 'ভারী ক্রলার ও টাওয়ার ক্রেন', 'বিপজ্জনক বর্জ্য সংরক্ষণাগার', 'শ্রমিক সুরক্ষা ও প্রশিক্ষণ কেন্দ্র', 'প্রাথমিক চিকিৎসাকেন্দ্র']::text[], array['Hazardous materials storage and containment according to HKC Regulation 16', 'Impermeable drainage system preventing oily discharge into marine waters']::text[], array['এইচকেসি বিধি ১৬ অনুযায়ী বিপজ্জনক উপকরণ সংরক্ষণ ও ব্যবস্থাপনা', 'সমুদ্রের পানিতে তেল নিষ্কাশন রোধে অপ্রবেশ্য ড্রেনেজ ব্যবস্থা']::text[], array['Mandatory Personal Protective Equipment (PPE) protocol', 'Continuous gas-free inspection prior to hot work', 'On-site trained emergency response team']::text[], array['বাধ্যতামূলক ব্যক্তিগত সুরক্ষা সরঞ্জাম (পিপিই) নীতি', 'হট ওয়ার্কের পূর্বে নিয়মিত গ্যাস-মুক্ত নিশ্চিতকরণ পরীক্ষা', 'ইয়ার্ডে প্রশিক্ষিত জরুরি উদ্ধার ও অগ্নিনির্বাপণ দল']::text[], array['Asbestos, PCB and heavy metals segregation and documented safe disposal', 'Bilge water and oil sludge treatment']::text[], array['অ্যাসবেস্টস, পিসিবি এবং ভারী ধাতু পৃথকীকরণ ও নিয়ন্ত্রিত নিষ্কাশন', 'বিলজ পানি এবং তেলের বর্জ্য শোধন']::text[], '/photos/imo-green-yard.jpg', array['/photos/imo-green-yard.jpg', '/photos/imo-green-recycling-sustainable.jpg', '/photos/bulk-carrier-recycling.jpg']::text[], 1, true),
